import sys
from collections import defaultdict, deque

def is_tree(graph, start, visited):
    queue = deque([start])
    visited[start] = True
    parent = {start: None}
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                parent[neighbor] = node
                queue.append(neighbor)
            elif parent[node] != neighbor:
                return False
    return True

def find_cycle(graph, n):
    visited = [False] * (n + 1)
    for i in range(1, n + 1):
        if not visited[i]:
            stack = [(i, None)]
            while stack:
                node, parent = stack.pop()
                if visited[node]:
                    continue
                visited[node] = True
                for neighbor in graph[node]:
                    if neighbor == parent:
                        continue
                    if visited[neighbor]:
                        return True, node, neighbor
                    stack.append((neighbor, node))
    return False, None, None

def is_cthulhu(graph, n, m):
    cycle_exists, u, v = find_cycle(graph, n)
    if not cycle_exists:
        return False
    visited = [False] * (n + 1)
    visited[u] = visited[v] = True
    trees_count = 0
    for i in range(1, n + 1):
        if visited[i]:
            continue
        if not is_tree(graph, i, visited):
            return False
        trees_count += 1
    return trees_count >= 2

